import{_ as e,o as t,c as n,ai as s}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"英文技术面试","description":"","frontmatter":{},"headers":[],"relativePath":"guide/english-interview/index.md","filePath":"guide/english-interview/index.md"}'),i={name:"guide/english-interview/index.md"};function r(l,a,d,p,h,o){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="英文技术面试" tabindex="-1">英文技术面试 <a class="header-anchor" href="#英文技术面试" aria-label="Permalink to “英文技术面试”">​</a></h1><p>这不是英语学习栏目，也不是语法 / 单词 / 雅思教程。</p><p>定位只有一句话：</p><blockquote><p><strong>把已经掌握的技术能力，用简单、稳定、清楚的英语表达出来，以便参加英文技术面试。</strong></p></blockquote><p>我的问题不是不懂 Java，而是：面试官用英语问我时，能不能快速、简单地讲清楚。</p><hr><h2 id="为什么做这个专题" tabindex="-1">为什么做这个专题 <a class="header-anchor" href="#为什么做这个专题" aria-label="Permalink to “为什么做这个专题”">​</a></h2><p>目标链路：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>技术能力</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>英文表达</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>英文技术面试</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>英文远程岗位</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>我有 10+ 年 Java / 全栈经验，做过企业业务系统和 MES / 工业数字化，正在往 AI 应用 / Agent 方向转，也在找远程开发岗位。</p><p>不需要从零学英语。需要的是：<strong>把已有技术能力，转成能开口的面试表达。</strong></p><hr><h2 id="_90-天目标" tabindex="-1">90 天目标 <a class="header-anchor" href="#_90-天目标" aria-label="Permalink to “90 天目标”">​</a></h2><h3 id="能说清楚自己" tabindex="-1">能说清楚自己 <a class="header-anchor" href="#能说清楚自己" aria-label="Permalink to “能说清楚自己”">​</a></h3><ul><li>30 秒自我介绍</li><li>60 秒自我介绍</li><li>90 秒自我介绍</li></ul><h3 id="能讲清楚项目" tabindex="-1">能讲清楚项目 <a class="header-anchor" href="#能讲清楚项目" aria-label="Permalink to “能讲清楚项目”">​</a></h3><p>至少 3 个：</p><ol><li>MES / 工业数字化</li><li>企业级 Java / 全栈</li><li>AI 应用 / Agent / AI 漫剧平台</li></ol><p>每个项目按同一骨架讲：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Background → Responsibility → Tech Stack → Architecture</span></span>
<span class="line"><span>→ Challenge → Solution → Result</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>没有真实数据就不虚构；正在做的写成 design / prototype / current development。</p><h3 id="能回答技术问题" tabindex="-1">能回答技术问题 <a class="header-anchor" href="#能回答技术问题" aria-label="Permalink to “能回答技术问题”">​</a></h3><p>Java、JVM、并发、MySQL、Redis、MQ、Spring、微服务、分布式、AI、Agent——用英语解释，不重新学一遍技术。</p><h3 id="能处理真实面试交流" tabindex="-1">能处理真实面试交流 <a class="header-anchor" href="#能处理真实面试交流" aria-label="Permalink to “能处理真实面试交流”">​</a></h3><p>这些不是「英语技巧」，是英文技术面试的生存能力：</p><table tabindex="0"><thead><tr><th>情况</th><th>可以说</th></tr></thead><tbody><tr><td>没听懂</td><td>Sorry, could you repeat the question?</td></tr><tr><td>需要确认</td><td>Do you mean the database consistency issue?</td></tr><tr><td>需要思考</td><td>Let me think about that for a moment.</td></tr><tr><td>不会</td><td>I haven&#39;t worked with it directly, but I&#39;ve worked with similar technologies.</td></tr><tr><td>举例</td><td>Let me explain it with an example.</td></tr><tr><td>换说法</td><td>Let me rephrase that.</td></tr><tr><td>纠正自己</td><td>Let me correct that. / Let me rephrase that.</td></tr></tbody></table><p>英文面试不是演讲，是技术沟通。听不懂、不确定、需要举例，都是正常沟通动作。</p><hr><h2 id="当前内容" tabindex="-1">当前内容 <a class="header-anchor" href="#当前内容" aria-label="Permalink to “当前内容”">​</a></h2><p>第一阶段只建训练框架，不堆空文章：</p><ul><li><strong><a href="./90-day-plan.html">90天英文技术面试计划</a></strong> — 主训练页</li><li><strong><a href="./self-introduction.html">Self Introduction</a></strong> — 30 / 60 / 90 秒 + 追问（训练稿，会持续改）</li></ul><p>后续随真实训练逐步补：项目介绍、技术题、面试场景、模拟面试记录。</p><p>原则：</p><blockquote><p><strong>训练产生内容，而不是为了网站制造内容。</strong></p></blockquote><hr><h2 id="和其他栏目的边界" tabindex="-1">和其他栏目的边界 <a class="header-anchor" href="#和其他栏目的边界" aria-label="Permalink to “和其他栏目的边界”">​</a></h2><table tabindex="0"><thead><tr><th>栏目</th><th>负责什么</th></tr></thead><tbody><tr><td><strong>英文技术面试</strong></td><td>如何用英语表达已有技术能力</td></tr><tr><td><a href="/my-vitepress-site/ai/dev/">AI → 技术</a></td><td>AI / Agent 知识本身</td></tr><tr><td>就业指南里的 Java / Redis 等</td><td>中文技术面试知识</td></tr><tr><td><a href="/my-vitepress-site/guide/agent/">Agent 面试</a></td><td>Agent 中文面试怎么答</td></tr></tbody></table><p>例如：HashMap 的完整原理不在这里重写；这里只准备 <em>How would I explain HashMap in an interview?</em></p><hr><h2 id="怎么开始" tabindex="-1">怎么开始 <a class="header-anchor" href="#怎么开始" aria-label="Permalink to “怎么开始”">​</a></h2><ol><li>读完本页，明确目标不是「学好英语」，而是「90 天后能完成英文技术面试」</li><li>进入 <a href="./90-day-plan.html">90天计划</a></li><li>从第 1 周自我介绍开始练；每天约 40 分钟：<strong>Speaking &gt; Listening &gt; Writing &gt; Grammar</strong></li></ol>`,41)])])}const g=e(i,[["render",r]]);export{b as __pageData,g as default};
